def topo_sort(graph):
    # Build in-degree count and reverse adjacency list
    in_degree = {}
    reverse_adj = {}

    # Initialize all nodes with 0 in-degree
    for node in graph:
        if node not in in_degree:
            in_degree[node] = 0
        for dep in graph[node]:
            if dep not in in_degree:
                in_degree[dep] = 0
            if node not in reverse_adj:
                reverse_adj[node] = []
            reverse_adj[dep].append(node)

    # Calculate in-degrees
    for node in graph:
        for dep in graph[node]:
            in_degree[node] += 1

    # Kahn's algorithm
    queue = [node for node in in_degree if in_degree[node] == 0]
    result = []

    while queue:
        node = queue.pop(0)
        result.append(node)

        if node in reverse_adj:
            for neighbor in reverse_adj[node]:
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 0:
                    queue.append(neighbor)

    # Check for cycle
    if len(result) != len(in_degree):
        return None

    return result
```

