def parse_csv(text):
    if not text:
        return []

    lines = text.splitlines()
    if not lines:
        return []

    # Parse header
    header = parse_csv_line(lines[0])
    result = []

    for line in lines[1:]:
        if line.strip():  # Skip empty lines
            fields = parse_csv_line(line)
            if len(fields) == len(header):
                result.append(dict(zip(header, fields)))

    return result

def parse_csv_line(line):
    """Parse a single CSV line handling quoted fields."""
    fields = []
    current_field = ""
    in_quotes = False
    i = 0

    while i < len(line):
        char = line[i]

        if in_quotes:
            if char == '"':
                # Check for escaped quote (doubled)
                if i + 1 < len(line) and line[i + 1] == '"':
                    current_field += '"'
                    i += 2
                    continue
                else:
                    # End of quoted field
                    in_quotes = False
                    i += 1
                    continue
            else:
                current_field += char
        else:
            if char == '"':
                # Start of quoted field (should be at beginning or after comma)
                in_quotes = True
            elif char == ',':
                # End of field
                fields.append(current_field)
                current_field = ""
            else:
                current_field += char

        i += 1

    # Add the last field
    fields.append(current_field)

    return fields
```

