def normalize(path):
    if not path:
        return '.'

    # Check if absolute
    is_absolute = path.startswith('/')

    # Split by '/' and filter out empty strings and '.'
    parts = [p for p in path.split('/') if p and p != '.']

    # Process '..'
    result = []
    for part in parts:
        if part == '..':
            if result and result[-1] != '..':
                result.pop()
            elif not is_absolute:
                # For relative paths, keep leading '..'
                result.append('..')
        else:
            result.append(part)

    # Construct normalized path
    if is_absolute:
        return '/' + '/'.join(result) if result else '/'
    else:
        return '/'.join(result) if result else '.'
```

