def deep_get(obj, path, default=None):
    if not path:
        return obj

    # Split the path by dots
    parts = path.split('.')

    current = obj
    for part in parts:
        # Check if current is a dict or list
        if isinstance(current, dict):
            if part in current:
                current = current[part]
            else:
                return default
        elif isinstance(current, list):
            # Try to convert part to integer index
            try:
                idx = int(part)
                if 0 <= idx < len(current):
                    current = current[idx]
                else:
                    return default
            except (ValueError, IndexError):
                return default
        else:
            # Not a dict or list, can't go deeper
            return default

    return current
```

