import hashlib
import json

def stable_hash(obj):
    def make_stable(obj):
        if isinstance(obj, dict):
            return {k: make_stable(v) for k, v in sorted(obj.items())}
        elif isinstance(obj, list):
            return [make_stable(item) for item in obj]
        else:
            return obj

    stable_obj = make_stable(obj)
    json_str = json.dumps(stable_obj, sort_keys=True, separators=(',', ':'))
    return hashlib.sha256(json_str.encode('utf-8')).hexdigest()
