function debounceCount(fn, ms) {
  let timer = null;
  let pendingArgs = [];

  function call(...args) {
    clearTimeout(timer);
    pendingArgs.push(args);
    timer = setTimeout(() => {
      const argsToInvoke = pendingArgs;
      pendingArgs = [];
      fn(...argsToInvoke);
    }, ms);
  }

  function flush() {
    clearTimeout(timer);
    if (pendingArgs.length > 0) {
      const argsToInvoke = pendingArgs;
      pendingArgs = [];
      fn(...argsToInvoke);
    }
  }

  return { call, flush };
}

module.exports = debounceCount;
