function parseQuery(qs) {
  const result = {};

  if (!qs || typeof qs !== 'string') {
    return result;
  }

  // Remove leading '?' if present
  const cleanQs = qs.startsWith('?') ? qs.slice(1) : qs;

  if (!cleanQs) {
    return result;
  }

  const pairs = cleanQs.split('&');

  for (const pair of pairs) {
    if (!pair) continue;

    const [key, value] = pair.split('=');
    const decodedKey = decodeURIComponent(key.replace(/\+/g, ' '));

    if (decodedKey === '') continue;

    const decodedValue = value !== undefined 
      ? decodeURIComponent(value.replace(/\+/g, ' '))
      : '';

    if (result.hasOwnProperty(decodedKey)) {
      if (!Array.isArray(result[decodedKey])) {
        result[decodedKey] = [result[decodedKey]];
      }
      result[decodedKey].push(decodedValue);
    } else {
      result[decodedKey] = decodedValue;
    }
  }

  return result;
}

module.exports = parseQuery;
```

