function rotateArray(arr, k) {
  if (arr.length === 0) return [];

  const n = arr.length;
  // Normalize k to handle cases where k > n or k is negative
  const normalizedK = ((k % n) + n) % n;

  // If normalizedK is 0, return a copy of the original array
  if (normalizedK === 0) return [...arr];

  // Rotate right by k: take last k elements and put them at the front
  const rotated = [...arr.slice(-normalizedK), ...arr.slice(0, n - normalizedK)];
  return rotated;
}

module.exports = rotateArray;
