export function chunk<T>(arr: T[], n: number): T[][] {
  if (n <= 0) {
    throw new Error('chunk size must be positive');
  }

  const result: T[][] = [];
  for (let i = 0; i < arr.length; i += n) {
    result.push(arr.slice(i, i + n));
  }
  return result;
}
