Here’s a complete example of how to implement this API endpoint using Node.js with Express and TypeScript (with JSDoc for documentation). The logic includes validation, ownership verification, and appropriate HTTP status codes.

---

### **API Endpoint Specification**

- **Method & Path:** `PUT /api/v1/users/{id}`
- **Request Body (JSON):**
  ```json
  {
    "name": "string",
    "email": "string"
  }
  ```
- **Responses:**
  - `200 OK`: User updated successfully.
  - `400 Bad Request`: Validation error (e.g., missing fields, invalid email).
  - `403 Forbidden`: User attempts to edit another user’s profile.

---

### **Implementation (Express + TypeScript)**

```ts
import { Request, Response, NextFunction } from 'express';
import { validationResult, body, ValidationChain } from 'express-validator';

// --- Mock User Repository ---
interface User {
  id: string;
  name: string;
  email: string;
}

const users: Record<string, User> = {
  '123': { id: '123', name: 'Alice', email: 'alice@example.com' },
  '456': { id: '456', name: 'Bob', email: 'bob@example.com' },
};

// --- Validation Rules ---
const validateUserInput: ValidationChain[] = [
  body('name')
    .trim()
    .notEmpty().withMessage('Name is required')
    .isLength({ max: 100 }).withMessage('Name must be ≤ 100 characters'),
  body('email')
    .trim()
    .notEmpty().withMessage('Email is required')
    .isEmail().withMessage('Invalid email format'),
];

// --- Middleware: Extract authenticated user ID ---
// In real apps, this would come from JWT or session
const getCurrentUserId = (req: Request): string | null => {
  // For demo, extract from header or query param
  return req.headers['x-current-user-id'] as string | null;
};

// --- Route Handler ---
export const updateUser = async (
  req: Request,
  res: Response,
  next: NextFunction
) => {
  const { id } = req.params;
  const currentUserId = getCurrentUserId(req);

  // 1. Validate input
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  // 2. Check ownership (403 Forbidden)
  if (currentUserId !== id) {
    return res.status(403).json({ error: 'Forbidden: You can only edit your own profile' });
  }

  // 3. Update user
  const { name, email } = req.body;

  if (!users[id]) {
    return res.status(404).json({ error: 'User not found' });
  }

  users[id] = { ...users[id], name, email };

  // 4. Return updated user (200 OK)
  return res.status(200).json(users[id]);
};

